#:property InvariantGlobalization=false
#:property PublishAot=false

// Find the earliest Friday the 13th in the proleptic Gregorian calendar (from 0001-01-01)
// and count all Friday the 13ths in a full 400-year cycle.

// --- Earliest Friday the 13th ---
DateOnly earliest = default;
for (int year = 1; year <= 9999; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            earliest = d;
            goto found;
        }
    }
}
found:
Console.WriteLine($"Earliest Friday the 13th: {earliest:yyyy-MM-dd}");

// --- Count in a full 400-year cycle (years 1–400) ---
int count = 0;
var byMonth = new int[12];
for (int year = 1; year <= 400; year++)
{
    for (int month = 1; month <= 12; month++)
    {
        var d = new DateOnly(year, month, 13);
        if (d.DayOfWeek == DayOfWeek.Friday)
        {
            count++;
            byMonth[month - 1]++;
        }
    }
}

Console.WriteLine($"\nFriday the 13ths in a 400-year cycle: {count}");
Console.WriteLine($"Average per year: {count / 400.0:F4}");
Console.WriteLine();
Console.WriteLine("Breakdown by month:");
for (int m = 0; m < 12; m++)
{
    var name = new DateOnly(2000, m + 1, 1).ToString("MMMM");
    Console.WriteLine($"  {name,-12} {byMonth[m],3}");
}

